inventory.label:
{
              mode === "login"
                ? "New here? Create an account"
                : "Already learning? Sign in"
            }

{
            item.kind === "listen"
              ? "Sentence to speak aloud"
              : "Sentence to read"
          }

{
            item.kind === "fill"
              ? "Prompt (include ___ for the blank)"
              : "Prompt"
          }

{
                  item.correct === i
                    ? "✓ Correct answer"
                    : "Set as correct answer"
                }

{
            r.recording
              ? `Stop · ${Math.floor(r.duration / 1000)}s`
              : "Record a voice reference"
          }

{
                      d.status === "published"
                        ? "Unpublish course"
                        : "Publish course"
                    }

{
                        d.visibility === "public"
                          ? "Limit to assigned classes"
                          : "Make publicly discoverable"
                      }

{
                        d.sequential
                          ? "Allow any lesson order"
                          : "Require lesson order"
                      }

{
            pack ? "Refresh practice download" : "Download public practice"
          }

{
                        (data.difficulty === d ? "✓ " : "") +
                        (d === "starter"
                          ? "Build foundations"
                          : "Stretch myself")
                      }

{
              index === sample.length - 1
                ? "Try the sample again"
                : "Next sample"
            }

{
                  review.data?.items?.length
                    ? "Start your review"
                    : "Find my next practice"
                }

{
                        r.reason === "delayed_check_due"
                          ? "Time for a fresh check"
                          : "Revisit a recent correction"
                      }

{
                index === items.length - 1
                  ? "Finish practice"
                  : "Next small step"
              }

{
              disputed
                ? "Restore this evidence"
                : "The transcript isn’t what I said"
            }

{
          user?.role === "teacher"
            ? "Saved drafts & archives"
            : "My goals & continuous practice"
        }
